SELECT DATE_TRUNC('QUARTER', paid_at) AS quarter_start, CASE WHEN amount >= 1340 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, SUM(amount) FILTER (WHERE method = 'card') AS card_total_amount, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'FAILED' THEN 1 END), 0), 2) AS amount_per_failed, APPROX_PERCENTILE(amount, 0.95) AS amount_p95 FROM payments GROUP BY CUBE (DATE_TRUNC('QUARTER', paid_at), CASE WHEN amount >= 1340 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING amount_p95 > 0 ORDER BY amount_tier DESC;
